// deploy is safe in either direction: a pre-#6134 pod (enum = “{auto, batch}“) and a post-fix
// pod (enum = “{auto, standard, batch}“) can both deserialise payloads the other produces.
// Migration plan (three stages, each a separate PR fully deployed before the next): 1. **Widen**
// *(this PR)*: enum = “{AUTO, STANDARD, BATCH}“, “default=AUTO“. Compatible with the
// still-running pre-#6134 prod pods after yesterday's rollback. 2. **Flip default**: same enum,
// “default=STANDARD“. Ship after stage 1 is everywhere. 3. **Narrow** *(future, optional)*: drop
// “AUTO“ once every Redis payload and SDK has migrated. Until then it stays as an accepted
// alias.
type QueuePriority string

const (
	QueuePriorityAuto     QueuePriority = "auto"
	QueuePriorityStandard QueuePriority = "standard"
	QueuePriorityBatch    QueuePriority = "batch"
)

